Copy the workbook, then read the hire dates, term dates, and month headers from Sheet1. For each month, count employees whose hire date is on/before the month start and whose term date is blank or on/after that month start. Write the twelve counts as plain values into E2:P2.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def to_dt(v):
    if v is None or v == "":
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)):
        return datetime(1899, 12, 30) + timedelta(days=float(v))
    try:
        return datetime.fromisoformat(str(v).strip()[:19])
    except Exception:
        return None

counts = []
for col in range(5, 17):  # E through P
    month = to_dt(vws.cell(row=1, column=col).value)
    cnt = 0

    if month is not None:
        for row in range(2, 23):  # rows 2 through 22
            hire = to_dt(vws.cell(row=row, column=1).value)
            term = to_dt(vws.cell(row=row, column=2).value)

            if hire is None:
                continue

            if hire <= month and (term is None or term >= month):
                cnt += 1

    ws.cell(row=2, column=col).value = cnt
    counts.append(cnt)

print("computed counts:", counts)
wb.save(OUT)
```

